import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.C9_66ieh.js";const u=JSON.parse('{"title":"TrueDeck vs BridgeSpace - product gaps","description":"","frontmatter":{},"headers":[],"relativePath":"bridgespace-parity.md","filePath":"bridgespace-parity.md","lastUpdated":1785285552000}'),o={name:"bridgespace-parity.md"};function s(n,t,i,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="truedeck-vs-bridgespace-product-gaps" tabindex="-1">TrueDeck vs BridgeSpace - product gaps <a class="header-anchor" href="#truedeck-vs-bridgespace-product-gaps" aria-label="Permalink to &quot;TrueDeck vs BridgeSpace - product gaps&quot;">​</a></h1><p>TrueDeck aims to be a <strong>free, open-source BridgeSpace-class multi-agent deck</strong>: real CLI agents in a terminal grid, a kanban that dispatches them, dual memory, and (next) a code knowledge graph + orchestration.</p><p>TrueDeck identity: <strong>orchestrate vendor CLIs</strong> (Grok, Codex, Claude, Cursor Agent, …) - not replace them with an in-house chat IDE.</p><h2 id="memory-layers-dual-graph" tabindex="-1">Memory layers (dual + graph) <a class="header-anchor" href="#memory-layers-dual-graph" aria-label="Permalink to &quot;Memory layers (dual + graph)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Role</th><th>Status</th></tr></thead><tbody><tr><td><strong>TrueMemory</strong></td><td>Markdown under <code>.memory/</code> + global app-data notes</td><td>Shipped</td></tr><tr><td><strong>MemPalace</strong></td><td>Graph/vector palace via native MCP</td><td>Shipped (native)</td></tr><tr><td><strong>Graphify</strong></td><td>Code/structure graph (<code>graphify-out/</code>)</td><td><strong>Automatic</strong> (under the hood)</td></tr></tbody></table><p><strong>User-facing:</strong> memory and Graphify stay automatic. Choose which CLIs to keep wired (<code>syncedAgentIds</code>; default = all coding agents). TrueDeck injects MCP + memory into those CLIs on project open and agent launch, warms palace + graph, and refreshes the graph after agent work.</p><p>Agents still use all three when available via <code>.truedeck/auto-context.md</code> and env.</p><h2 id="gap-matrix-summary" tabindex="-1">Gap matrix (summary) <a class="header-anchor" href="#gap-matrix-summary" aria-label="Permalink to &quot;Gap matrix (summary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>BridgeSpace</th><th>TrueDeck</th><th>Status</th></tr></thead><tbody><tr><td>Multi-pane agent terminals (≤16)</td><td>Yes</td><td>Nested pane dock, <code>MAX_PANES=16</code></td><td><strong>Have</strong></td></tr><tr><td>Named layout presets</td><td>Yes</td><td>Session restore only</td><td>Missing</td></tr><tr><td>Kanban → dispatch agent</td><td>BridgeBoard</td><td>Task board + <code>dispatchTask</code></td><td><strong>Have</strong></td></tr><tr><td>Multi-agent pipelines / swarm</td><td>BridgeSwarm</td><td>Roles + orchestrator</td><td><strong>Building</strong></td></tr><tr><td>Git worktree isolation</td><td>Common</td><td>Setting stub</td><td><strong>Building</strong></td></tr><tr><td>Knowledge graph</td><td>Product UI</td><td>Graphify integrate + sync</td><td><strong>Building</strong></td></tr><tr><td>Memory product</td><td>BridgeMemory</td><td>Dual TrueMemory + MemPalace</td><td><strong>Have</strong> (polish UX)</td></tr><tr><td>Review / browser / voice / SSH</td><td>Yes</td><td>Not started</td><td>Later packs</td></tr></tbody></table><h2 id="delivery-phases-status" tabindex="-1">Delivery phases (status) <a class="header-anchor" href="#delivery-phases-status" aria-label="Permalink to &quot;Delivery phases (status)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Phase</th><th>Status</th></tr></thead><tbody><tr><td>0</td><td>Docs + tab labels</td><td>Done</td></tr><tr><td>1</td><td>Graphify core (auto)</td><td>Done</td></tr><tr><td>2</td><td>Agent roles</td><td>Done</td></tr><tr><td>3</td><td>Git worktree isolation</td><td>Done</td></tr><tr><td>4</td><td>Graphify auto sync</td><td>Done</td></tr><tr><td>5</td><td>Pipelines + orchestrator</td><td>Done (<code>truedeck_start_pipeline</code> MCP)</td></tr><tr><td>6</td><td>Graph + dual memory in context</td><td>Done (auto-context / env)</td></tr><tr><td>7</td><td>Run history</td><td>Done (task/run store; list via MCP)</td></tr><tr><td>8</td><td>Layouts + review</td><td>Done (IPC/layouts; review via git tools)</td></tr><tr><td>9</td><td>Browser / voice / SSH</td><td>Deferred</td></tr></tbody></table><p><strong>Deck actions are MCP-first</strong> (<code>truedeck_launch</code>, pipelines, tasks) - no deck tools UI panel.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./task-board">Task board</a></li><li><a href="./memory-providers">Memory providers</a></li><li><a href="./architecture">Architecture</a></li><li><a href="./mcp">MCP</a></li></ul>',14)])])}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
